<script setup lang="ts">import {ref,computed} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Empty from '../components/common/Empty.vue';import Status from '../components/common/Status.vue';import Table from '../components/common/Table.vue';import InferenceSummary from '../components/InferenceSummary.vue';import StateBands from '../components/StateBands.vue';import PosteriorGrid from '../components/PosteriorGrid.vue';import ConstraintMarks from '../components/ConstraintMarks.vue';import ProfileMatrix from '../components/ProfileMatrix.vue';import {fmt,prob,constraintReason} from '../utils/format';const p=defineProps<{runs:any[];selectedId:number}>(),emit=defineEmits(['open']),traceId=ref(0),run=computed(()=>p.runs.find(r=>r.id===p.selectedId)||p.runs[0]),trace=computed(()=>run.value?.result?.traces.find(t=>t.id===traceId.value)||run.value?.result?.traces[0]);function open(e:Event){emit('open',p.runs.find(r=>r.id===Number((e.target as HTMLSelectElement).value)))}function pickTrace(e:Event){traceId.value=Number((e.target as HTMLSelectElement).value)}</script><template><PageTitle index="04" title="单点分布，与整段联合路径分开读。" description="前向后向得到边际后验；Viterbi得到固定模型下整段联合MAP。标记隐态假设后，后验与联合路径都只在满足标记的路径集合内计算。"/><label>结果运行<select :value="run?.id||0" @change="open"><option v-for="r in runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><p v-if="run"><Status :value="run.status"/>　{{run.error}}</p><template v-if="run?.result"><InferenceSummary :result="run.result"/><label>观测轨迹<select :value="trace?.id||0" @change="pickTrace"><option v-for="t in run.result.traces" :key="t.id" :value="t.id">{{t.reference}}{{t.constraint_mode==='conditional'?' 〔标记〕':''}}</option></select></label><div class="trace-metrics"><span>无约束序列logL <strong>{{fmt(trace.log_likelihood,8)}}</strong></span><span>无约束联合MAP logP <strong>{{fmt(trace.viterbi_log_joint,8)}}</strong></span><span>{{prob(trace.likelihood_if_representable,{underflows:trace.linear_likelihood_underflows})}}</span><template v-if="trace.constraint_mode==='conditional'"><span>约束成立概率 <strong>{{prob(trace.constraint_probability,{underflows:trace.constraint_probability_underflows,trueZero:trace.constraint_probability_is_true_zero})}}</strong></span><span>条件logL <strong>{{trace.conditional_log_likelihood===null?'—':fmt(trace.conditional_log_likelihood,8)}}</strong></span><span>条件联合MAP logP <strong>{{trace.conditional_viterbi_log_joint===null?'—':fmt(trace.conditional_viterbi_log_joint,8)}}</strong></span></template></div><ConstraintMarks :trace="trace" :states="run.result.states"/><StateBands :trace="trace" :states="run.result.states"/><PosteriorGrid :trace="trace" :states="run.result.states"/><section class="section"><h2>所选轨迹逐条核对</h2><Table :headers="['轨迹','步数','隐态标记','无约束logL','无约束联合MAP logP','约束成立概率','条件logL','条件联合MAP logP','首个无可行步','拼接合法性']"><tr v-for="t in run.result.traces" :key="t.id"><td>{{t.reference}}</td><td>{{t.tokens.length}}</td><td>{{t.constraints?.length?t.constraints.map((c:any)=>c.step+':'+c.allowed_states.join('/')).join('；'):'无约束'}}</td><td>{{fmt(t.log_likelihood,7)}}</td><td>{{fmt(t.viterbi_log_joint,7)}}</td><td>{{t.constraint_mode==='conditional'?prob(t.constraint_probability,{underflows:t.constraint_probability_underflows,trueZero:t.constraint_probability_is_true_zero}):'—'}}</td><td>{{t.conditional_log_likelihood===null?'—':fmt(t.conditional_log_likelihood,7)}}</td><td>{{t.conditional_viterbi_log_joint===null?'—':fmt(t.conditional_viterbi_log_joint,7)}}</td><td><span :class="{copper:t.constraint_status==='conflict'}">{{t.constraint_conflict?('第'+t.constraint_conflict.first_infeasible_step+'步 · '+(t.constraint_conflict.stage==='model'?'模型':'观测')):'—'}}</span></td><td>{{t.marginal_path_is_legal?'无约束拼接可行（仍非联合定义）':'无约束拼接非法零概率路径'}}{{t.constraint_mode==='conditional'&&t.constraint_status==='satisfied'?(t.conditional_marginal_path_is_legal?'；条件拼接可行':'；条件拼接非法'):''}}</td></tr></Table></section><ProfileMatrix :profile="run.result.profile"/><details class="provenance"><summary>冻结指纹与所选轨迹完整log数组</summary><p class="fingerprint">{{run.result.fingerprint}}</p><p>指纹算法版本 {{run.result.fingerprint_version||'fixed-hmm-log-fb-viterbi-v1'}}（旧运行无此字段时按历史版本读取；不含标记时保持与旧数据可比）。</p><p>{{trace.tie_rule}}</p><p>{{trace.null_log_meaning}}</p><Table :headers="['步','观测','log forward','log backward','条件log forward','条件log backward']"><tr v-for="(token,i) in trace.tokens" :key="i"><td>{{Number(i)+1}}</td><td>{{token}}</td><td>{{JSON.stringify(trace.log_forward[i])}}</td><td>{{JSON.stringify(trace.log_backward[i])}}</td><td>{{trace.conditional_log_forward?JSON.stringify(trace.conditional_log_forward[i]):'—'}}</td><td>{{trace.conditional_log_backward?JSON.stringify(trace.conditional_log_backward[i]):'—'}}</td></tr></Table></details><div class="boundary-note"><strong>隐态由固定模型定义，不是故障事实。</strong><p>标记只表示“该时刻的隐态假设有待核对”，条件结果不改变固定π/A/B，也不把无约束似然替换成条件似然。</p></div><a href="#notes" class="text-action">建立工况核对说明 →</a></template><Empty v-else :title="run?.status==='failed'?'本次观测在模型下不可行或推断失败':'等待真实worker推断'" :help="run?.error||'核对观测字母表与模型后，选择1–30条轨迹排队。'"/></template>
